#include <bits/stdc++.h>
using namespace std;

using U128 = bitset<128>;

const int MOD = 1000000007;
const int INV = 570000004;

int add_mod(int a, int b) {
    int res = a + b;
    return res >= MOD ? res - MOD : res;
}

int sub_mod(int a, int b) {
    int res = a - b;
    return res < 0 ? res + MOD : res;
}

int mul_mod(int a, int b) {
    return (int)((1LL * a * b) % MOD);
}

unordered_map<U128, int> index_map;
int node_id, time_counter, children_array[65536][128];

int dfs(U128 state) {
    auto it = index_map.find(state);
    if (it != index_map.end()) return it->second;
    int id = time_counter++;
    index_map[state] = id;
    for (int mask = 0; mask < (1 << node_id); ++mask) {
        U128 new_state = state;
        for (int j = 0; j < (1 << node_id); ++j) {
            if (!new_state[j]) {
                for (int k = mask & j; k; k ^= k & -k) {
                    if (state[j ^ (k & -k)]) {
                        new_state[j] = 1;
                        break;
                    }
                }
            }
        }
        children_array[id][mask] = dfs(new_state);
    }
    return id;
}

int p[7][7], q[7][128], dp[8][65536];

int main() {
    int n;
    cin >> n;
    dfs(U128(1));
    for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) {
