import java.util.*;
import java.util.stream.Collectors;

public class Main {
    static class U128 {
        BitSet bits;
        public U128() {
            bits = new BitSet(128);
        }
        public U128(BitSet bits) {
            this.bits = (BitSet) bits.clone();
        }
        public boolean get(int index) {
            return bits.get(index);
        }
        public void set(int index, boolean value) {
            bits.set(index, value);
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof U128)) return false;
            U128 u128 = (U128) o;
            return Objects.equals(bits, u128.bits);
        }
        @Override
        public int hashCode() {
            return Objects.hash(bits);
        }
        public U128 clone() {
            return new U128(bits);
        }
        public static U128 fromArray(boolean[] arr) {
            U128 u = new U128();
            for (int i = 0; i < arr.length; i++) {
                if(arr[i]) u.set(i, true);
            }
            return u;
        }
    }

    static final int MOD = 1000000007;
    static final int INV = 570000004;

    static int add_mod(int a, int b) {
        int res = a + b;
        return res >= MOD ? res - MOD : res;
    }

    static int sub_mod(int a, int b) {
        int res = a - b;
        return res < 0 ? res + MOD : res;
    }

    static int mul_mod(int a, int b) {
        return (int)((long)a * b % MOD);
    }

    static Map<U128, Integer> index_map = new HashMap<>();
    static int node_id, time_counter;
    static int[][] children_array;
    static int[] p = new int[7][7];
    static int[][] q;
    static int[][] dp;

    static int dfs(U128 state) {
        if (index_map.containsKey(state))
            return index_map.get(state);
        int id = time_counter++;
        index_map.put(state, id);
        for (int mask = 0; mask < (1 << node_id); ++mask) {
            U128 new_state = state.clone();
            for (int j = 0; j < (1 << node_id); ++j) {
                if (!new_state.get(j)) {
                    int k_mask = mask & j;
                    for (; k_mask != 0; k_mask ^= (k_mask & -k_mask)) {
                        int k_bit = (k_mask & -k_mask);
                        int k_index = Integer.numberOfTrailingZeros(k_bit);
                        if (state.get(j ^ k_bit) && (k_mask != 0)) {
                            new_state.set(j, true);
                            break;
                        }
                    }
                }
            }
            children_array[id][mask] = dfs(new_state);
        }
        return id;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        index_map.clear();
        node_id = 0;
        time_counter = 0;

        // Initiate dfs with U128(1): only first bit set
        U128 startState = new U128();

        startState.set(0, true); // equivalent to U128(1) in bits
        dfs(startState);
        node_id = index_map.size();

        children_array = new int[node_id][1 << n];
        q = new int[n][1 << n];
        dp = new int[n + 1][node_id];

        for (int i = 0; i < n; i++) {
            for (int j2 = 0; j2 < n; j2++) {
                p[i][j2] = sc.nextInt();
                p[i][j2] = mul_mod(p[i][j2], INV);
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j2 = 0; j2 < (1 << n); j2++) {
                q[i][j2] = 1;
                for (int k = 0; k < n; k++) {
                    int val = (((j2 >> k) & 1) == 1) ? p[k][i] : sub_mod(1, p[k][i]);
                    q[i][j2] = mul_mod(q[i][j2], val);
                }
            }
        }

        Arrays.fill(dp[0], 0);
        dp[0][0] = 1;

        for (int i = 0; i < n; i++) {
            for (int j2 = 0; j2 < node_id; j2++) {
                for (int k2 = 0; k2 < (1 << n); k2++) {
                    int next_state = children_array[j2][k2];
                    dp[i + 1][next_state] = add_mod(dp[i + 1][next_state],
                            mul_mod(dp[i][j2], q[i][k2]));
                }
            }
        }

        U128 res = new U128();
        for (int i = 0; i < (1 << n); i++) {
            res.set(i, true);
        }
        Integer index = index_map.get(res);
        System.out.println(dp[n][index != null ? index : -1]);
        sc.close();
    }
}
